import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import axios from 'axios';

const Dashboard = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [stats, setStats] = useState(null);
  const [recentSubmissions, setRecentSubmissions] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      // Fetch user stats
      const statsResponse = await axios.get(`${process.env.REACT_APP_API_URL}/submissions/stats`);
      setStats(statsResponse.data);

      // Fetch recent submissions
      const submissionsResponse = await axios.get(`${process.env.REACT_APP_API_URL}/submissions/user`);
      setRecentSubmissions(submissionsResponse.data.submissions?.slice(0, 5) || []);
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div style={styles.loadingContainer}>
        <div className="loading-spinner"></div>
        <p>Loading dashboard...</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      {/* Navigation Bar */}
      <nav style={styles.nav}>
        <div style={styles.navLeft}>
          <h1 style={styles.logo}>⚡ CodeArena</h1>
        </div>
        <div style={styles.navRight}>
          <button onClick={() => navigate('/problems')} style={styles.navButton}>
            📚 Problems
          </button>
          <button onClick={() => navigate('/submissions')} style={styles.navButton}>
            📊 Submissions
          </button>
          {(user?.role === 'admin' || user?.role === 'setter') && (
            <button onClick={() => navigate('/create-problem')} style={styles.createButton}>
              ➕ Create Problem
            </button>
          )}
          <button onClick={logout} style={styles.logoutButton}>
            🚪 Logout
          </button>
        </div>
      </nav>

      {/* Welcome Section */}
      <div style={styles.welcomeSection}>
        <div>
          <h2 style={styles.welcomeTitle}>Welcome back, {user?.username}! 👋</h2>
          <p style={styles.welcomeSubtitle}>Role: {user?.role}</p>
        </div>
        <div style={styles.badgeContainer}>
          <span style={styles.badge}>
            {user?.role === 'admin' ? '🔑 Admin' : 
             user?.role === 'setter' ? '✍️ Setter' : '🎓 Student'}
          </span>
        </div>
      </div>

      {/* Stats Cards */}
      <div style={styles.statsGrid}>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>✅</div>
          <div>
            <h3 style={styles.statLabel}>Problems Solved</h3>
            <p style={styles.statNumber}>{user?.stats?.problemsSolved || 0}</p>
          </div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>📝</div>
          <div>
            <h3 style={styles.statLabel}>Total Attempts</h3>
            <p style={styles.statNumber}>{user?.stats?.totalAttempts || 0}</p>
          </div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>📊</div>
          <div>
            <h3 style={styles.statLabel}>Success Rate</h3>
            <p style={styles.statNumber}>
              {user?.stats?.totalAttempts > 0 
                ? Math.round((user.stats.problemsSolved / user.stats.totalAttempts) * 100)
                : 0}%
            </p>
          </div>
        </div>
      </div>

      {/* Recent Activity */}
      <div style={styles.recentSection}>
        <h3 style={styles.sectionTitle}>📋 Recent Activity</h3>
        {recentSubmissions.length === 0 ? (
          <p style={styles.emptyMessage}>No submissions yet. Start solving problems!</p>
        ) : (
          <div style={styles.submissionList}>
            {recentSubmissions.map((sub, index) => (
              <div key={sub._id || index} style={styles.submissionItem}>
                <div>
                  <span style={styles.submissionProblem}>{sub.problem?.title || 'Unknown'}</span>
                  <span style={styles.submissionLanguage}>{sub.language?.toUpperCase()}</span>
                </div>
                <div>
                  <span style={{
                    ...styles.submissionStatus,
                    ...(sub.status === 'accepted' ? styles.statusAccepted : styles.statusFailed)
                  }}>
                    {sub.status === 'accepted' ? '✅ Passed' : '❌ Failed'}
                  </span>
                  <span style={styles.submissionScore}>{sub.score?.toFixed(0)}%</span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Quick Actions */}
      <div style={styles.quickActions}>
        <h3 style={styles.sectionTitle}>🚀 Quick Actions</h3>
        <div style={styles.actionGrid}>
          <div style={styles.actionCard} onClick={() => navigate('/problems')}>
            <div style={styles.actionIcon}>📚</div>
            <p style={styles.actionLabel}>Browse Problems</p>
          </div>
          <div style={styles.actionCard} onClick={() => navigate('/submissions')}>
            <div style={styles.actionIcon}>📊</div>
            <p style={styles.actionLabel}>View Submissions</p>
          </div>
          {(user?.role === 'admin' || user?.role === 'setter') && (
            <div style={styles.actionCard} onClick={() => navigate('/create-problem')}>
              <div style={styles.actionIcon}>➕</div>
              <p style={styles.actionLabel}>Create Problem</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

